-- Reference data for the customer Markets overview (read-only, no secrets).
-- Universe and sectors: NSE Nifty 50 constituent list, as downloaded 2026-11-09 (as_of).
-- Index tokens: Angel One public scrip master (exch_seg NSE, instrumenttype AMXIDX).
CREATE TABLE market_index_definition (index_code VARCHAR(32) PRIMARY KEY, display_name VARCHAR(80) NOT NULL, symbol_token VARCHAR(32) NOT NULL UNIQUE, sort_order INT NOT NULL CHECK (sort_order > 0));
CREATE TABLE market_universe_member (universe_code VARCHAR(32) NOT NULL, trading_symbol VARCHAR(64) NOT NULL, company_name VARCHAR(200) NOT NULL, sector VARCHAR(80) NOT NULL, source VARCHAR(160) NOT NULL, as_of DATE NOT NULL, PRIMARY KEY (universe_code, trading_symbol), CHECK (trading_symbol ~ '^[A-Z0-9&._-]{1,50}-EQ$'));
